# Settle the selected claims together, in list order, by the signed-in user. Each that can be settled is settled
# (or left PENDING, audited and rolled up) as a single settle is; each that cannot is left as it is. Responds with
# how many of each.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.BulkSettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Settle each selected claim by the signed-in user, in list order (people in the order they were added, newest
 *  claim first within a person), by exactly the rules of settling one claim: each that goes through (SETTLED, or
 *  PENDING for a clerk's settle above the clerk limit) gets its status log line, its CLAIM_SETTLED or CLAIM_PENDING
 *  line (with its NOTIFY lines for the person's watchers when SETTLED) and then how the sheet's figures moved over it.
 *  When at least one goes through, the bulk settle is the sheet's next batch and each that went through is settled by
 *  it. A selected claim that cannot be settled (the sheet is archived, not on the sheet,
 *  not allowed from its status or by this user, or dated in a closed period) is left as it is and counted as
 *  refused. */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimRepository claims,
            ClaimLogRepository log, PersonRepository people, PeriodRepository periods, RateRepository rates,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets, Rollups rollups,
            WatchRepository watches, SettleBatchRepository batches, Audit audit, Out<BulkSettleResponse> result) {
        String sheet = sheetId.trim();
        periods.lockSheet(sheet);
        ClaimStatusInput settle = new ClaimStatusInput(input.user(), "settle", ClaimStatus.SETTLED, null);
        int settled = 0;
        Integer batch = null;
        if (sheets.archived(sheet)) {
            result.set(new BulkSettleResponse(0, input.claimIds().size()));
            return;
        }
        for (Person person : people.list(sheet)) {
            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
                    .filter(c -> input.claimIds().contains(c.id())).toList();
            for (Claim claim : theirs) {
                if (periods.closedOn(sheet, claim.dueBy()) != null) {
                    continue;
                }
                Rollup before = rollups.take(sheet);
                ClaimResponse saved;
                try {
                    saved = ClaimStatusChange.save(settle, claim, claims, people, rates, roles, settings, sheets, log);
                } catch (ClaimStatusNotAllowedException refused) {
                    continue;
                }
                if (batch == null) {
                    batch = batches.start(sheet);
                }
                batches.settledBy(sheet, claim.id(), batch);
                ClaimStatusChange.audit(settle, claim, saved, people, watches, audit);
                rollups.record(sheet, input.user(), before);
                settled++;
            }
        }
        result.set(new BulkSettleResponse(settled, input.claimIds().size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import java.util.LinkedHashSet;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and at least one selected claim. */
public class ValidateBulkSettle {
    public void validate(@RequestBody BulkSettleRequest request, Out<BulkSettleInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before settling claims.");
        }
        if (request.claimIds() == null || request.claimIds().isEmpty()) {
            throw new InvalidClaimException("Select the claims to settle.");
        }
        body.set(new BulkSettleInput(request.user().trim(), new LinkedHashSet<>(request.claimIds())));
    }
}
package net.officefloor.hq.app.claim;

import java.util.Set;

/** A validated bulk settle: who is settling and the selected claim ids. */
public record BulkSettleInput(String user, Set<Long> claimIds) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkSettle {
    public void respond(@Val BulkSettleResponse result, ObjectResponse<BulkSettleResponse> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashMap;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's settle batches: each bulk settle that settled at least one claim (one left PENDING counts), numbered
 *  1, 2, ... on the sheet in the order they happened, and the batch that settled each claim (none for a claim settled
 *  one at a time). */
@Repository
public class SettleBatchRepository {

    private final JdbcTemplate jdbc;

    public SettleBatchRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The number of the sheet's last batch; null when there has been none. */
    public Integer last(String sheetId) {
        return jdbc.query("SELECT MAX(batch) FROM settle_batch WHERE sheet_id = ?",
                rs -> rs.next() ? (Integer) rs.getObject(1, Integer.class) : null, sheetId);
    }

    /** Start the sheet's next batch: its number. */
    public int start(String sheetId) {
        Integer last = last(sheetId);
        int next = last != null ? last + 1 : 1;
        jdbc.update("INSERT INTO settle_batch (sheet_id, batch) VALUES (?, ?)", sheetId, next);
        return next;
    }

    /** Record the claim as settled by the batch. */
    public void settledBy(String sheetId, long claimId, int batch) {
        jdbc.update("MERGE INTO claim_batch KEY (sheet_id, claim_id) VALUES (?, ?, ?)", sheetId, claimId, batch);
    }

    /** Record the claim as settled one at a time: by no batch. */
    public void settledAlone(String sheetId, long claimId) {
        jdbc.update("DELETE FROM claim_batch WHERE sheet_id = ? AND claim_id = ?", sheetId, claimId);
    }

    /** The batch that settled each claim on the sheet a bulk settle settled, by claim id. */
    public Map<Long, Integer> byClaim(String sheetId) {
        Map<Long, Integer> batches = new HashMap<>();
        jdbc.query("SELECT claim_id, batch FROM claim_batch WHERE sheet_id = ?",
                rs -> {
                    batches.put(rs.getLong(1), rs.getInt(2));
                }, sheetId);
        return batches;
    }
}

