test("batch all or nothing scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  await ui.setSetting(pg_uma, "grace-B", "2");
  await ui.setSetting(pg_uma, "proof-threshold-C", "0.50");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": "ben@x"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "20", "contact": "ben@x"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20"}));
  await ui.setToday(pg_uma, "2026-04-30");
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00", "tags": "b,a,a"}));
  expect(await ui.editClaim(pg_uma, c_ada_0, {"amount": "0.40"})).toBe(true);
  expect(await ui.editClaim(pg_uma, c_ada_0, {"date": "2026-03-05"})).toBe(true);

